#include "fur_surface_attachment_candidate.h"
#include <iostream>
int main(){try{std::vector<GeometryDeformedVertexCandidate>surface(3);surface[0].position={0,0,0};surface[1].position={4,0,0};surface[2].position={0,4,0};for(auto&v:surface)v.normal={0,0,2};FurSurfaceAnchorCandidate anchor{{0,1,2},{0.5f,0.25f,0.25f},3};auto first=sampleFurSurfaceGuidesCandidate({anchor},surface).at(0);if(first.root!=std::array<float,3>{1,1,0}||first.tip!=std::array<float,3>{1,1,3})throw std::runtime_error("rest guide mismatch");for(auto&v:surface){v.position={v.position[0]+10,0,v.position[1]+20};v.normal={0,-2,0};}auto moved=sampleFurSurfaceGuidesCandidate({anchor},surface).at(0);if(moved.root!=std::array<float,3>{11,0,21}||moved.tip!=std::array<float,3>{11,-3,21})throw std::runtime_error("animated attachment mismatch");surface[1].position[0]+=4;auto deformed=sampleFurSurfaceGuidesCandidate({anchor},surface).at(0);if(deformed.root[0]!=12)throw std::runtime_error("deformation attachment mismatch");unsigned rejected=0;for(unsigned i=0;i<5;++i){auto bad=anchor;auto vertices=surface;if(i==0)bad.vertices[2]=3;if(i==1)bad.weights[0]=-1;if(i==2)bad.weights[0]=0;if(i==3)bad.length=INFINITY;if(i==4)for(auto&v:vertices)v.normal={0,0,0};try{sampleFurSurfaceGuidesCandidate({bad},vertices);}catch(const std::runtime_error&){++rejected;}}if(rejected!=5)throw std::runtime_error("invalid fur attachment accepted");FurTopologyCandidate topology{"model",123,0,3,{{0,1,2}}};FurSurfaceAttachmentSetCandidate owned(topology,{anchor});auto ownedGuide=owned.sample(topology,surface)[0];if(ownedGuide.root!=deformed.root||ownedGuide.tip!=deformed.tip)throw std::runtime_error("owned guide changed");unsigned topologyRejected=0;for(unsigned i=0;i<5;++i){auto bad=topology;if(i==0)bad.modelName="other";if(i==1)bad.checksum=124;if(i==2)bad.lod=1;if(i==3)bad.vertexCount=4;if(i==4)bad.triangles[0]={0,2,1};try{owned.sample(bad,surface);}catch(const std::runtime_error&){++topologyRejected;}}if(topologyRejected!=5)throw std::runtime_error("topology change accepted");std::cout<<"fur_topology_rejections=5 owned_guide_exact=true\n";std::cout<<"fur_attachment_checks=3 invalid_rejections=5 animated_translation_rotation_deformation length_preserved renderer=unfinished\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
